from z3 import *

# ----- Data -------------------------------------------------
houses = [1, 2]

# Enumerations for each attribute category
name_vals = {"Eric": 0, "Arnold": 1}
flower_vals = {"carnations": 0, "daffodils": 1}
color_vals = {"red": 0, "yellow": 1}
height_vals = {"very short": 0, "short": 1}

# Reverse maps for printing
rev_name = {v: k for k, v in name_vals.items()}
rev_flower = {v: k for k, v in flower_vals.items()}
rev_color = {v: k for k, v in color_vals.items()}
rev_height = {v: k for k, v in height_vals.items()}

# ----- Variables --------------------------------------------
# name[h] = which person lives in house h (0..1)
name = {h: Int(f"name_{h}") for h in houses}
flower = {h: Int(f"flower_{h}") for h in houses}
color = {h: Int(f"color_{h}") for h in houses}
height = {h: Int(f"height_{h}") for h in houses}

s = Solver()

# Domain constraints (each variable must be 0 or 1)
for h in houses:
    s.add(And(name[h] >= 0, name[h] <= 1))
    s.add(And(flower[h] >= 0, flower[h] <= 1))
    s.add(And(color[h] >= 0, color[h] <= 1))
    s.add(And(height[h] >= 0, height[h] <= 1))

# Each attribute appears exactly once across the two houses
s.add(Distinct([name[h] for h in houses]))
s.add(Distinct([flower[h] for h in houses]))
s.add(Distinct([color[h] for h in houses]))
s.add(Distinct([height[h] for h in houses]))

# ----- Clues ------------------------------------------------
# 1. The person who loves a bouquet of daffodils is in the first house.
s.add(flower[1] == flower_vals["daffodils"])

# 2. The person who is very short is not in the first house.
s.add(height[1] != height_vals["very short"])

# 3. The person whose favorite color is red is in the first house.
s.add(color[1] == color_vals["red"])

# 4. Eric is not in the second house.
s.add(name[2] != name_vals["Eric"])

# ----- Solve ------------------------------------------------
if s.check() == sat:
    m = s.model()
    for h in sorted(houses):
        n = rev_name[m[name[h]].as_long()]
        f = rev_flower[m[flower[h]].as_long()]
        c = rev_color[m[color[h]].as_long()]
        ht = rev_height[m[height[h]].as_long()]
        print(f"House {h}: {n}, {f}, {c}, {ht}")
else:
    print("No solution found.")

from z3 import *

# variables for each attribute value representing house number (1 or 2)
NameArnold = Int('NameArnold')
NameEric = Int('NameEric')
HeightShort = Int('HeightShort')
HeightVeryShort = Int('HeightVeryShort')
PetCat = Int('PetCat')
PetDog = Int('PetDog')
NatBrit = Int('NatBrit')
NatDane = Int('NatDane')
ColorYellow = Int('ColorYellow')
ColorRed = Int('ColorRed')
MotherAniya = Int('MotherAniya')
MotherHolly = Int('MotherHolly')

s = Solver()

# domain constraints
vars = [NameArnold, NameEric, HeightShort, HeightVeryShort, PetCat, PetDog,
        NatBrit, NatDane, ColorYellow, ColorRed, MotherAniya, MotherHolly]

for v in vars:
    s.add(Or(v == 1, v == 2))

# distinctness per category
s.add(Distinct(NameArnold, NameEric))
s.add(Distinct(HeightShort, HeightVeryShort))
s.add(Distinct(PetCat, PetDog))
s.add(Distinct(NatBrit, NatDane))
s.add(Distinct(ColorYellow, ColorRed))
s.add(Distinct(MotherAniya, MotherHolly))

# clues
s.add(HeightShort == 2)                     # clue1
s.add(NameEric == NatDane)                  # clue2
s.add(ColorRed == NameArnold)               # clue3
s.add(MotherHolly + 1 == NatBrit)           # clue4
s.add(MotherHolly == PetCat)                # clue5

# solve
if s.check() == sat:
    m = s.model()
    # helper to get attribute name for a house
    def get_name(h):
        if m[NameArnold].as_long() == h:
            return "Arnold"
        else:
            return "Eric"
    def get_height(h):
        if m[HeightShort].as_long() == h:
            return "short"
        else:
            return "very short"
    def get_pet(h):
        if m[PetCat].as_long() == h:
            return "cat"
        else:
            return "dog"
    def get_nat(h):
        if m[NatBrit].as_long() == h:
            return "brit"
        else:
            return "dane"
    def get_color(h):
        if m[ColorYellow].as_long() == h:
            return "yellow"
        else:
            return "red"
    def get_mother(h):
        if m[MotherAniya].as_long() == h:
            return "Aniya"
        else:
            return "Holly"

    for h in [1,2]:
        print(f"House {h}: {get_name(h)}, {get_height(h)}, {get_pet(h)}, {get_nat(h)}, {get_color(h)}, {get_mother(h)}")
else:
    print("No solution")
